// Package html renders distinct semantic CV document systems for every Tengeneza template.
package html

import (
	"bytes"
	stdhtml "html/template"

	"github.com/troubleman96/tengeneza-cv-desktop/internal/render/model"
)

type Renderer struct{}

func (Renderer) Render(doc model.Document) (string, error) {
	template, err := stdhtml.New("cv").Funcs(stdhtml.FuncMap{"tr": func(value string) string { return model.Translate(doc.Language, value) }}).Parse(pageFor(doc.TemplateID))
	if err != nil {
		return "", err
	}
	var output bytes.Buffer
	if err := template.Execute(&output, doc); err != nil {
		return "", err
	}
	return output.String(), nil
}

func pageFor(id string) string {
	switch id {
	case "graduate_launch":
		return content + graduateLaunch
	case "skilled_trades":
		return content + skilledTrades
	case "remote_async":
		return content + remoteAsync
	case "creative_producer":
		return content + creativeProducer
	case "consulting_strategy":
		return content + consultingStrategy
	case "engineering_blueprint":
		return content + engineeringBlueprint
	case "public_service":
		return content + publicService
	case "nonprofit_impact":
		return content + nonprofitImpact
	case "clinical_care":
		return content + clinicalCare
	case "educator_classroom":
		return content + educatorClassroom
	case "sales_growth":
		return content + salesGrowth
	case "field_operations":
		return content + fieldOperations
	case "creative_portfolio":
		return content + creativePortfolio
	case "tech_product":
		return content + techProduct
	case "finance_audit":
		return content + financeAudit
	case "legal_chambers":
		return content + legalChambers
	case "ats_modern":
		return content + modern
	case "global_minimal":
		return content + globalMinimal
	case "executive_ats":
		return content + executive
	case "visual_local":
		return content + visualLocal
	case "hospitality_local":
		return content + hospitality
	case "academic_cv":
		return content + academic
	case "career_change":
		return content + career
	default:
		return content + classic
	}
}

const content = `{{define "content"}}
{{if .Summary}}<section class="summary-section"><h2>{{tr "Professional Summary"}}</h2><p>{{.Summary}}</p></section>{{end}}
{{if .HardSkills}}<section class="skills-section"><h2>{{tr "Key Skills & Expertise"}}</h2><p class="skills">{{range $index,$skill:=.HardSkills}}{{if $index}} · {{end}}{{$skill}}{{end}}</p></section>{{end}}
{{if .Experience}}<section class="experience-section"><h2>{{tr "Work Experience"}}</h2>{{range .Experience}}<article class="experience"><div class="role"><span>{{.Title}}</span><span class="date">{{.StartDate}} – {{if .Current}}{{tr "Present"}}{{else}}{{.EndDate}}{{end}}</span></div><p class="employer">{{.Employer}}{{if .Location}} · {{.Location}}{{end}}</p><ul>{{range .Bullets}}<li>{{.}}</li>{{end}}</ul></article>{{end}}</section>{{end}}
{{if .Education}}<section class="education-section"><h2>{{tr "Education"}}</h2>{{range .Education}}<article class="education"><div class="role"><span>{{.Credential}}</span><span class="date">{{.StartDate}} – {{.EndDate}}</span></div><p>{{.Institution}}{{if .Location}} · {{.Location}}{{end}}{{if .Classification}} · {{.Classification}}{{end}}</p></article>{{end}}</section>{{end}}
{{if .Certifications}}<section class="certifications-section"><h2>{{tr "Certifications"}}</h2>{{range .Certifications}}<p>{{.Name}} — {{.Issuer}}{{if .Year}}, {{.Year}}{{end}}</p>{{end}}</section>{{end}}
{{if .Languages}}<section class="languages-section"><h2>{{tr "Languages"}}</h2><p>{{range $index,$language:=.Languages}}{{if $index}} · {{end}}{{$language.Name}} ({{$language.Proficiency}}){{end}}</p></section>{{end}}
{{end}}`

